speculative_score_draft: {
  // tempo: 117 bpm, key: C minor
  // progression: | Cm | Ab | Eb | Bb |

  // Global FX
  const reverb = new Tone.Reverb({ decay: 4, wet: 0.8 }).toDestination();

  // Distorted Lead (MonoSynth)
  const leadSynth = new Tone.MonoSynth({
    oscillator: { type: 'sawtooth' },
    envelope: { attack: 0.02, decay: 0.4, sustain: 0.5, release: 0.6 },
    filterEnvelope: { attack: 0.05, decay: 0.2, sustain: 0.2, release: 1, baseFrequency: 300, octaves: 4 },
    portamento: 0.08
  });
  const leadFx = new Tone.Distortion(0.6).connect(reverb);
  leadSynth.connect(leadFx);
  const leadPart = new Tone.Sequence(..., ['G4', 'F4', 'Eb4'], '16n');

  // 16th Arp (PolySynth)
  const arpSynth = new Tone.PolySynth(Tone.Synth, {
    oscillator: { type: 'square' },
    envelope: { attack: 0.01, decay: 0.1, sustain: 0.1, release: 0.1 },
    volume: -18
  }).connect(reverb);
  const arpPart = new Tone.Pattern(..., ['C5', 'G4', 'Eb5', 'G4'], 'up');

  // Supersaw Pad (PolySynth)
  const padSynth = new Tone.PolySynth(Tone.Synth, {
    oscillator: { type: 'fatsawtooth', count: 6, spread: 35 },
    envelope: { attack: 0.4, release: 1.8 },
    volume: -20
  });
  const padFx = new Tone.Chorus(4, 2.5, 0.5).connect(reverb);
  padSynth.connect(padFx);
  const padPart = new Tone.Part(..., [{time: '0:0', note: 'Cm4', duration: '1m'}]);
}
